window.CASH_HINTS.push(...[{"id": "hint35-0", "answer": "Kemal Sunal", "hints": ["Türk sinemasında özellikle komedi rolleriyle tanınan bir oyuncudur. Sıradan insanların yaşadığı sorunları mizahla anlatan filmlerde oynamıştır.", "Hababam Sınıfı serisinde unutulmaz bir öğrenci karakterini canlandırmıştır. Aynı seride Münir Özkul ile kamera karşısına geçmiştir.", "Tosun Paşa ve Süt Kardeşler filmlerinin oyuncu kadrolarında yer almıştır. Bu filmler televizyonlarda yıllarca yeniden gösterilmiştir.", "Şaban adıyla özdeşleşen bu oyuncu Kapıcılar Kralı filminde de başroldedir. Filmde Seyit karakterini canlandırır.", "Hababam Sınıfı'ndaki İnek Şaban rolü onun en tanınmış karakterlerindendir. Adı Kemal olan sanatçının soyadı soruluyor."]}, {"id": "hint35-1", "answer": "Şener Şen", "hints": ["Türk sinemasında hem komedi hem dram filmlerinde başroller üstlenmiştir. Uzun kariyerinde sahne oyunculuğu da yapmıştır.", "Hababam Sınıfı filmlerinde Badi Ekrem karakterini canlandırmıştır. Öğrencilerle yaptığı beden eğitimi dersleriyle hatırlanır.", "Yavuz Turgul'un yönettiği Eşkıya filminde Baran rolünde izleyici karşısına çıkmıştır. Filmde Uğur Yücel ile birlikte oynamıştır.", "Züğürt Ağa filminde köyünü bırakarak İstanbul'a gelen bir ağayı canlandırır. Bu rolü komedi ile hüznü bir araya getirir.", "Muhsin Bey ve Gönül Yarası filmlerinin de başrol oyuncusudur. Babası da sinema oyuncusu Ali Şen'dir."]}, {"id": "hint35-2", "answer": "Barış Manço", "hints": ["Türk popüler müziğinde uzun saçları, bıyığı ve yüzükleriyle tanınan sanatçıdır. Müzisyen kimliğinin yanında televizyon programları da yapmıştır.", "Yurt dışında yaptığı gezileri ekrana taşımıştır. Çocuklarla kurduğu sıcak iletişim televizyon çalışmalarının önemli bir parçasıdır.", "7'den 77'ye adlı programı hazırlayıp sunmuştur. Program içinde Adam Olacak Çocuk bölümü de yer almıştır.", "Dağlar Dağlar ve Gülpembe onun seslendirdiği eserler arasındadır. Kurtalan Ekspres grubuyla birlikte çalışmıştır.", "Domates Biber Patlıcan ve Sarı Çizmeli Mehmet Ağa şarkılarıyla da bilinir. Adı Barış olan sanatçının soyadı soruluyor."]}, {"id": "hint35-3", "answer": "Sezen Aksu", "hints": ["Türk pop müziğinde şarkıcı ve söz yazarı olarak çok sayıda esere imza atmıştır. Başka sanatçıların söylediği birçok şarkıyı da yazmıştır.", "Müzik dünyasında Minik Serçe lakabıyla tanınır. Bu lakap bir sinema filminin adı olarak da kullanılmıştır.", "Gülümse ve Firuze onun en bilinen şarkıları arasındadır. Uzun yıllar farklı kuşaklardan dinleyicilere ulaşmıştır.", "Şarkıcılığının yanında birçok genç sanatçının yetişmesinde rol almıştır. Sahnede güçlü yorumuyla tanınır.", "Hadi Bakalım şarkısını da seslendiren sanatçıdır. Müzik dünyasında pek çok yorumcuya verdiği besteler ve şarkı sözleriyle tanınır."]}, {"id": "hint35-4", "answer": "Tarkan", "hints": ["Türk pop müziğinin uluslararası dinleyiciye ulaşan isimlerinden biridir. Almanya'da doğmuş ve müzik kariyerini Türkiye'de geliştirmiştir.", "Sahne dünyasında Megastar lakabıyla tanınır. Dansları ve hareketli pop şarkılarıyla bilinir.", "Şımarık şarkısı yurt dışında da geniş kitlelere ulaşmıştır. Klipteki öpücük sesi şarkının ayırt edici ayrıntılarındandır.", "Kuzu Kuzu ve Dudu adlı şarkıları da seslendirmiştir. Albüm adları arasında Karma bulunur.", "Sanatçı sahnede tek adıyla tanınır. Şıkıdım şarkısının da yorumcusudur."]}, {"id": "hint35-5", "answer": "Cem Karaca", "hints": ["Türk rock müziğinde güçlü sesiyle tanınan bir sanatçıdır. Anadolu ezgilerini rock düzenlemeleriyle buluşturmuştur.", "Kariyeri boyunca Apaşlar, Kardaşlar ve Dervişan gibi gruplarla çalışmıştır. Toplumsal konulu şarkılar da seslendirmiştir.", "Tamirci Çırağı adlı şarkıda çalışan bir gencin hikâyesini anlatmıştır. Şarkı Türk rock repertuvarının tanınmış eserlerindendir.", "Resimdeki Gözyaşları onun yorumuyla bilinir. Gözlükleri ve uzun saçları sahne görünümünün parçalarıdır.", "Islak Islak ve Namus Belası şarkıları onun yorumuyla da tanınır. Güçlü ve kendine özgü ses rengi Türk rock müziğinde ayırt edilir."]}, {"id": "hint35-6", "answer": "Lionel Messi", "hints": ["Arjantinli bir futbolcudur. Kariyerinde oyun kuruculuğu ve golcülüğü bir arada sergilemiştir.", "Rosario'da doğmuştur. Genç yaşta İspanya'ya giderek Barcelona'nın altyapısına katılmıştır.", "Barcelona'da uzun yıllar forma giymiştir. Kulüpte geçirdiği dönemde çok sayıda gol ve kupa kazanmıştır.", "2022 Dünya Kupası'nda Arjantin takımının kaptanıdır. Finalde Fransa'ya karşı oynayan takımda yer almıştır.", "Kariyerinde 10 numaralı formayla özdeşleşmiştir. Adı Lionel olan futbolcunun soyadı soruluyor."]}, {"id": "hint35-7", "answer": "Cristiano Ronaldo", "hints": ["Portekizli bir futbolcudur. Kariyeri boyunca farklı Avrupa liglerinde golcü olarak oynamıştır.", "Profesyonel kariyerinin ilk kulüplerinden biri Sporting'dir. Daha sonra Manchester United forması giymiştir.", "Real Madrid'de uzun yıllar oynamış ve kulübün gol rekorlarıyla anılmıştır. Juventus'ta da forma giymiştir.", "Portekiz milli takımıyla 2016 Avrupa Şampiyonası'nı kazanmıştır. Kariyerinde 7 numarayla özdeşleşmiştir.", "2018 yılında Real Madrid’den Juventus’a transfer olmuştur. Portekiz millî takımında da uzun yıllar golcü olarak forma giymiştir."]}, {"id": "hint35-8", "answer": "Arda Güler", "hints": ["Türk futbolunda genç yaşta dikkat çeken bir orta saha oyuncusudur. Sol ayağını etkili kullanmasıyla tanınır.", "Gençlerbirliği altyapısında futbola başlamıştır. Daha sonra Fenerbahçe'ye geçmiştir.", "Fenerbahçe'nin A takımında genç yaşta forma giymiştir. O dönemde attığı goller ve oyun görüşüyle öne çıkmıştır.", "2023 yılında Real Madrid'e transfer olmuştur. Türkiye milli takımında da oynamıştır.", "2024 Avrupa Şampiyonası’nda Gürcistan’a uzaktan attığı golle dikkat çekmiştir. Bu turnuvada Türkiye millî takımının formasını giymiştir."]}, {"id": "hint35-9", "answer": "Michael Jordan", "hints": ["Amerikalı bir basketbolcudur. Kariyeri özellikle NBA'deki başarılarıyla anılır.", "Uzun yıllar Chicago Bulls formasını giymiştir. Forma numarası olarak 23 ile özdeşleşmiştir.", "Chicago Bulls ile altı NBA şampiyonluğu kazanmıştır. Şampiyonlukların tamamında finalin en değerli oyuncusu seçilmiştir.", "Smaçları ve havada kalışı nedeniyle Air Jordan adıyla anılmıştır. Kendi adını taşıyan bir spor ayakkabısı serisi de vardır.", "Space Jam filminde çizgi film karakterleriyle birlikte kamera karşısına çıkmıştır. Adı Michael olan sporcunun soyadı soruluyor."]}, {"id": "hint35-10", "answer": "Harry Potter", "hints": ["Romanlardan sinemaya uyarlanan fantastik bir serinin başkahramanıdır. Çocuk yaşta büyücülük dünyasına adım atar.", "Hogwarts adlı okulda eğitim görür. En yakın arkadaşları arasında Ron ve Hermione bulunur.", "Alnında şimşek biçiminde bir yara izi vardır. Gözlükleri ve sihirli asasıyla tanınır.", "Hikâyelerinde Voldemort adlı karanlık büyücüyle mücadele eder. Baykuşu Hedwig de seride yer alır.", "J. K. Rowling'in yarattığı bu karakteri filmlerde Daniel Radcliffe canlandırmıştır. Adı Harry olan kahramanın soyadı soruluyor."]}, {"id": "hint35-11", "answer": "Yüzüklerin Efendisi", "hints": ["Fantastik edebiyatın sinemaya da uyarlanan bir serisidir. Hikâye Orta Dünya adlı kurmaca coğrafyada geçer.", "Hobbitler, elfler ve cüceler aynı hikâyede yer alır. Gandalf adlı büyücü önemli karakterlerden biridir.", "Frodo ve Sam adlı iki hobbit tehlikeli bir yolculuğa çıkar. Amaçları büyük bir gücün etkisini ortadan kaldırmaktır.", "Tek Yüzük adlı nesne hikâyenin merkezindedir. Sauron adlı karanlık güç bu nesnenin peşindedir.", "J. R. R. Tolkien'in eseridir. Sinema uyarlamasını Peter Jackson yönetmiştir."]}, {"id": "hint35-12", "answer": "Hababam Sınıfı", "hints": ["Bir okulun öğrencileriyle öğretmenleri arasındaki olayları komediyle anlatan eserdir. Hem kitap hem film olarak tanınır.", "Öğrenciler yatılı bir lisede eğitim görür. Derslerden kaçmak ve şakalaşmak hikâyelerin önemli parçalarıdır.", "Kel Mahmut adlı eğitimci öğrencilerini disipline etmeye çalışır. Öğrencilerin birbirlerine bağlılığı da anlatılır.", "İnek Şaban, Güdük Necmi ve Damat Ferit gibi karakterler aynı sınıfta yer alır. Filmlerde Adile Naşit de rol almıştır.", "Rıfat Ilgaz'ın eserinden sinemaya uyarlanmıştır. Yönetmen Ertem Eğilmez'in adıyla özdeşleşen film serisidir."]}, {"id": "hint35-13", "answer": "Avrupa Yakası", "hints": ["İstanbul'da geçen bir televizyon komedisidir. Bir aileyle bir derginin çalışanlarının günlük hayatını anlatır.", "Dizide Sütçüoğlu ailesi önemli yer tutar. Ailenin lokantası da hikâyelerin geçtiği mekânlardan biridir.", "Aslı ve Volkan adlı kardeşlerin etrafında birçok komik olay gelişir. Senaryosunu Gülse Birsel yazmıştır.", "Burhan Altıntop ve Şahika gibi karakterlerle tanınır. Ata Demirer ve Engin Günaydın kadroda yer alan isimlerdendir.", "Dizide Gülse Birsel, Aslı karakterini canlandırmıştır. Ata Demirer de Aslı’nın kardeşi Volkan rolünde kamera karşısına geçmiştir."]}, {"id": "hint35-14", "answer": "Leyla ile Mecnun", "hints": ["İstanbul'da geçen ve gerçeküstü olaylara yer veren bir televizyon dizisidir. Mizahla duygusal hikâyeleri birleştirir.", "Hikâyede bir genç adamın aşkı ve çevresindeki insanların hayatı anlatılır. Aksakallı Dede de karakterler arasındadır.", "Erdal Bakkal ve İsmail Abi bu dizinin tanınmış karakterleridir. İsmail'in kıyıda bekleyişi hatırlanan sahnelerdendir.", "Başrolde Ali Atay yer alır. Dizinin ilk yayın dönemindeki kanal TRT 1'dir.", "Dizide Erdal Bakkal’ı Cengiz Bozkurt, İskender’i Ahmet Mümtaz Taylan canlandırmıştır. Mahallede geçen sahneleriyle tanınır."]}, {"id": "hint35-15", "answer": "Eşkıya", "hints": ["1996 yılında gösterime giren bir Türk filmidir. Bir dostluk ve geçmişle hesaplaşma hikâyesini anlatır.", "Yavuz Turgul tarafından yönetilmiştir. Başrollerde Şener Şen ile Uğur Yücel yer alır.", "Hapisten çıkan Baran adlı karakter İstanbul'a gelir. Genç Cumali ile yolları burada kesişir.", "Baran geçmişinden gelen insanları ve sevdiği kadını arar. İstanbul'daki değişim hikâyenin önemli arka planıdır.", "Şener Şen'in Baran rolünü oynadığı filmin adı soruluyor. Adı dağlarda yaşayan silahlı kanun kaçakları için kullanılan bir sözcüktür."]}, {"id": "hint35-16", "answer": "Minecraft", "hints": ["Oyuncuların açık bir dünyada üretim ve keşif yaptığı video oyunudur. Dünyası küplerden oluşan bir görünüme sahiptir.", "Taş, odun ve maden gibi kaynaklar toplanır. Bu kaynaklarla araçlar ve yapılar hazırlanır.", "Hayatta kalma modunda yiyecek ve güvenli bir barınak önemlidir. Gece ortaya çıkan yaratıklarla karşılaşılabilir.", "Creeper adlı yeşil yaratıkla tanınır. Oyunda Nether ve End adlı farklı boyutlar da bulunur.", "Steve ve Alex adlı karakterlerle de anılan oyundur. Adı İngilizcede maden ve üretim sözcüklerini bir araya getirir."]}, {"id": "hint35-17", "answer": "Tetris", "hints": ["Ekrana yukarıdan gelen parçalarla oynanan klasik bir video oyunudur. Oyuncu parçaları döndürerek uygun yerlere yerleştirir.", "Parçalar dört kareden oluşan farklı biçimler taşır. Amaç arada boşluk bırakmadan dizilim kurmaktır.", "Yatay bir sıra tamamen dolduğunda o sıra ekrandan silinir. Yeni parçalar gelmeye devam eder.", "Alexey Pajitnov tarafından geliştirilmiştir. Çok sayıda oyun cihazına uyarlanmış bir bulmaca oyunudur.", "Uzun düz parça dört kareyi tek bir çizgide birleştirir. Oyuncular bu parçayla birden fazla yatay sırayı aynı anda tamamlayabilir."]}, {"id": "hint35-18", "answer": "İstanbul", "hints": ["Bir boğazın iki yakasına yayılan büyük bir şehirdir. Avrupa ile Asya kıtalarını aynı şehirde birleştirir.", "Tarih boyunca Roma ve Osmanlı gibi imparatorlukların başkentliğini yapmıştır. Çok sayıda tarihî yapı barındırır.", "Ayasofya ve Topkapı Sarayı bu şehirde bulunur. Tarihî yarımada ziyaretçilerin sık gittiği bölgelerdendir.", "Galata Kulesi ve Kız Kulesi şehrin simgeleri arasındadır. Boğazda vapur seferleri yapılır.", "Bir dönem Konstantinopolis adıyla anılmıştır. Türkiye'nin nüfusu en fazla olan şehridir."]}, {"id": "hint35-19", "answer": "Bursa", "hints": ["Marmara Bölgesi'ndeki tarihî bir şehirdir. Osmanlı Devleti'nin erken dönem başkentleri arasında yer alır.", "İpek ticareti ve tarihî hanlarıyla tanınır. Koza Han şehir merkezindeki simge yapılardandır.", "Uludağ kış sporları için ziyaret edilen önemli yerlerinden biridir. Teleferik de şehirle dağ arasında ulaşım sağlar.", "İskender kebabı ve kestane şekeriyle özdeşleşmiştir. Yeşil Türbe de bu şehrin simgelerindendir.", "İznik ve Orhangazi ilçeleri bu ilin sınırları içindedir. Marmara'nın güneyindeki büyük sanayi şehridir."]}, {"id": "hint35-20", "answer": "Kapadokya", "hints": ["Türkiye'nin İç Anadolu kesiminde bulunan turistik bir bölgedir. Kaya oluşumları ve tarihî yerleşimleriyle tanınır.", "Kayalara oyulmuş evler ve kiliseler bölgede görülebilir. Yer altı şehirleri de ziyaret edilir.", "Göreme ve Ürgüp bu bölgeyle anılan yerler arasındadır. Bölgenin önemli bölümü Nevşehir çevresindedir.", "Peribacaları denen kaya oluşumları simgesi hâline gelmiştir. Gün doğumunda balon turları düzenlenir.", "Derinkuyu ve Kaymaklı burada ziyaret edilebilen yer altı şehirleridir. Kayalara oyulmuş çok katlı tarihî yapılar da bölgeyi tanıtır."]}, {"id": "hint35-21", "answer": "Mimar Sinan", "hints": ["Osmanlı döneminde yaşamış bir mimardır. Çok sayıda cami, köprü ve su yapısının tasarımında rol almıştır.", "Kanuni Sultan Süleyman döneminde de görev yapmıştır. Başmimarlık göreviyle tanınır.", "İstanbul'daki Süleymaniye Camisi onun eserleri arasındadır. İstanbul'un siluetinde önemli yer tutan yapılar bırakmıştır.", "Edirne'deki Selimiye Camisi onun ustalık eseri olarak anılır. Yapı kubbesi ve minareleriyle tanınır.", "İstanbul’daki Şehzade Camisi de onun eseridir. Çıraklık, kalfalık ve ustalık eserleriyle anılan Osmanlı başmimarıdır."]}, {"id": "hint35-22", "answer": "Mehmet Akif Ersoy", "hints": ["Şair kimliğiyle tanınan bir Türk yazardır. Veterinerlik eğitimi de almıştır.", "Millî Mücadele döneminde yazıları ve konuşmalarıyla etkili olmuştur. Şiirlerinde toplumsal konulara yer vermiştir.", "Safahat adlı eserler bütünüyle tanınır. Eserleri Türk edebiyatında önemli bir yer tutar.", "İstiklal Marşı'nın sözlerini yazmıştır. Şiir 1921 yılında Türkiye Büyük Millet Meclisinde kabul edilmiştir.", "Çanakkale Şehitlerine şiirini de yazmıştır. Millî Mücadele yıllarındaki edebî çalışmalarıyla Türkiye’de millî şair olarak anılır."]}, {"id": "hint35-23", "answer": "Yaşar Kemal", "hints": ["Türk edebiyatında romanlarıyla tanınan bir yazardır. Eserlerinde doğa ve insan ilişkisine geniş yer verir.", "Çukurova onun romanlarında önemli bir coğrafyadır. Köylülerin hayatını güçlü betimlemelerle anlatmıştır.", "İnce Memed adlı romanının yazarıdır. Roman birçok dile çevrilmiştir.", "Yer Demir Gök Bakır ve Binboğalar Efsanesi de eserleri arasındadır. Asıl adı Kemal Sadık Gökçeli'dir.", "Demirciler Çarşısı Cinayeti adlı romanı da onun eseridir. Anlatılarında Anadolu’nun insanlarını ve doğasını güçlü bir dille işler."]}, {"id": "hint35-24", "answer": "Baklava", "hints": ["İnce hamur katlarıyla hazırlanan geleneksel bir tatlıdır. Katların arasında kuruyemiş kullanılabilir.", "Hazırlanırken yufkalar ince açılır ve tepsiye kat kat yerleştirilir. Üzerine eritilmiş yağ gezdirilir.", "Fırından çıktıktan sonra uygun sıcaklıktaki şerbetle buluşturulur. Cevizli ve fıstıklı çeşitleri yaygındır.", "Gaziantep bu tatlıyla özellikle tanınır. Dilimler çoğunlukla kare veya baklava biçiminde kesilir.", "Havuç dilimi ve kare gibi farklı kesimlerle servis edilebilir. İnce açılmış katlarının arasında kullanılan fıstık veya ceviz tadını belirler."]}, {"id": "hint35-25", "answer": "Voleybol", "hints": ["İki takımın fileyle ayrılan bir sahada karşılaştığı spordur. Top rakibin sahasına gönderilmeye çalışılır.", "Oyuncular topu elleri ve kollarıyla karşılar. Bir takım topu geri göndermeden önce en fazla üç vuruş yapabilir.", "Bir takım sahada aynı anda altı oyuncuyla yer alır. Oyunda pasör ve libero gibi görevler bulunur.", "Servisle başlayan ralliler oynanır. Hücumda smaç ve savunmada blok önemli hareketlerdir.", "Filenin üzerinden el ile top gönderilen bu sporun adı soruluyor. Türkiye kadın millî takımı Filenin Sultanları olarak anılır."]}, {"id": "hint35-26", "answer": "Basketbol", "hints": ["İki takımın bir topu rakibin hedefinden geçirmeye çalıştığı salon sporudur. Hızlı hücumlar ve paslaşma önemlidir.", "Hedef, sahanın iki ucunda bulunan yüksek bir çemberdir. Oyuncular topu sektirerek ilerler.", "Bir takım sahada aynı anda beş oyuncuyla yer alır. Başlıca görevler arasında oyun kurucu ve pivot bulunur.", "Serbest atış bir, çizgi dışındaki isabetli atış üç sayı değerindedir. NBA bu sporun tanınmış ligidir.", "Pota ve turuncu top ile özdeşleşen sporun adı soruluyor. Michael Jordan bu sporun ünlü isimlerindendir."]}, {"id": "hint35-27", "answer": "Tenis", "hints": ["Oyuncuların fileyle ayrılan bir sahada topa vurarak karşılaştığı spordur. Tekler ve çiftler olarak oynanabilir.", "Oyuncular topa ellerindeki telli araçla vurur. Saha toprak, çim veya sert zeminden oluşabilir.", "Puanlar sıfır, on beş, otuz ve kırk biçiminde anılır. Oyunlar birleşerek setleri oluşturur.", "Wimbledon bu sporun en eski turnuvalarındandır. Roger Federer ve Rafael Nadal bu sporla tanınır.", "Raket ve küçük sarı topla oynanan sporun adı soruluyor. Servis karşılamayla başlayan ralliler yapılır."]}, {"id": "hint35-28", "answer": "Çay", "hints": ["Yapraklarından sıcak bir içecek hazırlanan bitkidir. Türkiye'de günlük yaşamda sık tüketilir.", "Doğu Karadeniz'in yağışlı iklimi yetiştirilmesi için uygundur. Rize bu üretimle özellikle tanınır.", "Toplanan yapraklar işlenip kurutulur. Demleme sırasında sıcak suyla buluşur.", "Türkiye'de sıklıkla iki parçalı bir demlikle hazırlanır. İnce belli bardakla servis edilir.", "Sabah kahvaltılarında ve sohbetlerde ikram edilen sıcak içecektir. Demli ya da açık içilebilir."]}, {"id": "hint35-29", "answer": "Muz", "hints": ["Sıcak iklimlerde yetişen bir meyvedir. Ağaç görünümündeki iri otsu bitkilerde salkımlar hâlinde bulunur.", "Türkiye'de Akdeniz kıyısında yetiştirilir. Anamur bu meyveyle özellikle anılan yerlerdendir.", "Olgunlaştığında kabuğu çoğunlukla sarıya döner. Kabuğu elle soyularak yenir.", "Tatlılarda ve meyveli sütlerde kullanılabilir. Uzun ve kıvrık biçimiyle kolay tanınır.", "Spor yaparken ara öğünlerde de tüketilen bu meyve dilimlenerek yoğurt ve kahvaltılık karışımlara eklenebilir. Kabuğu elle soyulur."]}]);

(function(){const all=window.CASH_HINTS,entities=window.CASH_TOPICS.filter(t=>t.id.startsWith('entity33-'));for(let t of entities){let h=all.find(h=>h.answer===t.name);if(!h)continue;let other=all[(all.indexOf(h)+7)%all.length].answer;t.facts=[0,1,2].map((n)=>({id:t.id+'-35-'+n,text:(n===1?other:t.name)+' hakkında şu bilgi veriliyor: '+h.hints[n],correct:n!==1,explanation:'Bu bilgi '+t.name+' ile ilgilidir.'}));}})();

